DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 016", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "ddbfcc6e-ab54-5265-9aa6-4692a5d503da", "stem": "Which equation represents the graphed function?", "choices": [{"key": "A", "text": "f(x)=(x+1)(x−3)"}, {"key": "B", "text": "f(x)=(x−1)(x+3)"}, {"key": "C", "text": "f(x)=−(x+1)(x−3)"}, {"key": "D", "text": "f(x)=−(x−1)(x+3)"}], "type": "mcq", "correct": "C", "explanation": "The zeros are −1 and 3, and the parabola opens downward. Its y-intercept is 3, so f(x)=−(x+1)(x−3).", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 14", "note": "Complete original exam page 14 visually checked; answer independently solved and all choices checked. ", "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 034", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "c4ada32e-aa24-5ce3-87c5-00189e90d38f", "stem": "Let f(x)=2x²−3x+1 and g(x)=−3x+5. What is (f∘g)(−2)?", "choices": [], "type": "grid_in", "correct": "210", "explanation": "First g(−2)=6+5=11. Then f(11)=2(121)−33+1=210.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 41", "note": "Complete original exam page 41 visually checked; answer independently solved and all choices checked. The separate Joanne pay question is tracked by HOA 026 and remains held for ambiguous commission wording.", "assets": {}}, {"id": "clean:PSD 037", "old_status": "worked_missing_choice", "status": "ready", "question_id": "be5281b2-2df3-5203-a67e-54ac8daf8d71", "stem": "A stock price decreases by 20%, then decreases by 26%, and then increases by 30%. What is the overall percentage change?", "choices": [{"key": "A", "text": "Increased by 23.04%"}, {"key": "B", "text": "Decreased by 23.04%"}, {"key": "C", "text": "Decreased by 76.96%"}, {"key": "D", "text": "Increased by 76.96%"}], "type": "mcq", "correct": "B", "explanation": "The combined multiplier is (1−0.20)(1−0.26)(1+0.30)=0.8·0.74·1.3=0.7696. The price is 76.96% of its original value, a decrease of 23.04%.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 44", "note": "Complete original exam page 44 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:PSD 045", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "aca1d40a-c037-587f-ba40-6dc4cdd797f5", "stem": "In 2019, a club sold an average of 4,668 male, 1,102 female, and 884 child entrance tickets per game. Their respective revenues per game were $79,822.80, $15,428, and $4,420. What was the average revenue per entrance ticket?", "choices": [{"key": "A", "text": "$13.16"}, {"key": "B", "text": "$14.31"}, {"key": "C", "text": "$14.98"}, {"key": "D", "text": "$17.27"}], "type": "mcq", "correct": "C", "explanation": "Total revenue was 79822.80+15428+4420=$99670.80. The ticket count was 4668+1102+884=6654. Revenue per ticket was 99670.80/6654=$14.979…≈$14.98.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 47", "note": "Complete original exam page 47 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:PSD 049", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "0b570aa2-5e14-5b67-a72b-095414329596", "stem": "The dot plots show three distributions with the same mean. Which statement correctly compares their standard deviations σA, σB, and σC?", "choices": [{"key": "A", "text": "σA<σB<σC"}, {"key": "B", "text": "σA<σC<σB"}, {"key": "C", "text": "σC<σB<σA"}, {"key": "D", "text": "σB<σA<σC"}], "type": "mcq", "correct": "A", "explanation": "Standard deviation measures spread about the mean. Distribution A is most concentrated around the common mean; B is more spread out; C places the most data far from the mean. Hence σA<σB<σC.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 60", "note": "Complete original exam page 60 visually checked; answer independently solved and all choices checked. ", "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 069", "old_status": "needs_source_reconstruction", "status": "duplicate", "note": "Complete original exam page 79 visually checked; answer independently solved and all choices checked. Both percentages and all answer choices read from complete original bar chart; salary label is 20%, not an estimate from bar height. Worked solution: The full budget is 200000/0.125=$1600000. Salaries receive 20% of that, or $320000.", "correct": "A", "question_id": "5c9392df-6634-5759-b87a-1dd771ee5b1e", "duplicate_of": "topic:DAP 004"}, {"id": "clean:PSD 100", "old_status": "needs_source_reconstruction", "status": "duplicate", "note": "Complete original exam page 111 visually checked; answer independently solved and all choices checked.  The second question is the existing DAP 026, verified as 4 years (B). Worked solution: Honda is the dashed series: 800 cars in 2010 and 700 in 2015. The decline is (800−700)/800×100=12.5%.", "correct": "12.5", "question_id": "36278e2c-23dd-52c9-a36e-9a438161cbc7", "duplicate_of": "topic:DAP 027"}, {"id": "clean:PSD 112", "old_status": "worked_missing_choice", "status": "ready", "question_id": "8d72918a-586c-5c77-8801-cb424053ec64", "stem": "A school has 80 students. The numbers of females in first, second, and third secondary are 18, 17, and 5; the respective numbers of males are 12, 18, and 10. What is the probability that a randomly selected student is in second secondary?", "choices": [{"key": "A", "text": "17/35"}, {"key": "B", "text": "7/16"}, {"key": "C", "text": "30/80"}, {"key": "D", "text": "18/35"}], "type": "mcq", "correct": "B", "explanation": "Second secondary contains 17+18=35 students. The probability is 35/80=7/16.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 121", "note": "Complete original exam page 121 visually checked; answer independently solved and all choices checked. ", "assets": {}}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260929') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260929','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260929'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF q.id IS NOT NULL AND NOT (v ? 'before') THEN RAISE EXCEPTION 'Unexpected existing target %',qid; END IF;
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',coalesce(v->>'verification_source',s.source_document||' page '||s.source_page));
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260929','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260929','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-29. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260929';
